SET NAMES utf8mb4;
USE `0721acgn`;

CREATE TABLE IF NOT EXISTS `tb_galgame` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `slug` VARCHAR(64) NOT NULL COMMENT '稳定标识，用于去重与封面文件名',
  `name_zh` VARCHAR(255) NOT NULL COMMENT '中文名',
  `name_original` VARCHAR(255) DEFAULT NULL COMMENT '原名',
  `aliases` VARCHAR(512) DEFAULT NULL COMMENT '别名，/ 分隔',
  `short_intro` VARCHAR(500) DEFAULT NULL COMMENT '列表用简短介绍',
  `intro` TEXT COMMENT '详情用无剧透简介',
  `cover` VARCHAR(512) DEFAULT NULL COMMENT '封面地址',
  `developer` VARCHAR(255) DEFAULT NULL COMMENT '开发商',
  `release_date` VARCHAR(32) DEFAULT NULL COMMENT '首发日期',
  `release_year` INT DEFAULT NULL COMMENT '发行年份，用于年代筛选',
  `release_note` VARCHAR(255) DEFAULT NULL COMMENT '版本/平台发行说明',
  `platforms` VARCHAR(255) DEFAULT NULL COMMENT '支持平台',
  `genres` VARCHAR(512) DEFAULT NULL COMMENT '题材/标签，逗号分隔',
  `rating` DECIMAL(3,1) DEFAULT NULL COMMENT '评分（十分制）',
  `rating_count` INT DEFAULT NULL COMMENT '评分人数',
  `rating_source` VARCHAR(64) DEFAULT NULL COMMENT '评分来源',
  `rating_source_url` VARCHAR(512) DEFAULT NULL COMMENT '评分来源链接',
  `moegirl_url` VARCHAR(512) DEFAULT NULL,
  `bangumi_url` VARCHAR(512) DEFAULT NULL,
  `vndb_url` VARCHAR(512) DEFAULT NULL,
  `official_url` VARCHAR(512) DEFAULT NULL,
  `steam_url` VARCHAR(512) DEFAULT NULL,
  `sources_json` TEXT COMMENT '来源链接、采集时间与字段说明',
  `source_note` VARCHAR(500) DEFAULT NULL COMMENT '来源限制/版本说明',
  `featured` TINYINT NOT NULL DEFAULT 0 COMMENT '首页轮播推荐',
  `sort_order` INT NOT NULL DEFAULT 0 COMMENT '默认排序',
  `fetched_at` DATETIME DEFAULT NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_galgame_slug` (`slug`),
  KEY `idx_galgame_year` (`release_year`),
  KEY `idx_galgame_rating` (`rating`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Galgame 作品资料（VNDB/萌娘百科公开资料整理）';

INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('clannad', 'CLANNAD', 'CLANNAD', 'CLANNAD -クラナド- / CL', '在樱花坡道下，失去生活热情的高中生冈崎朋也遇见了独自伫立的古河渚。', '在樱花飘落的坡道下，对校园生活感到疏离的高中生冈崎朋也，遇见了独自伫立的少女古河渚。故事以学校、家庭和小镇居民为中心展开群像叙事，围绕“家族”这一主题，描写少年少女在相遇、相处与离别中逐渐找回生活温度的过程。作品包含恋爱、校园与亲情线，整体基调温暖而带有泪水。', '/galgame/clannad.jpg', 'Key', '2004-04-28', 2004, 'PC 初版；Steam HD 版于 2015-11-23 发行', 'PC (Windows) / iOS / Android / PSP / PS2 / PS3 / PS4 / PS Vita / Nintendo Switch / Xbox 360 / 手机', '恋爱,校园,剧情,治愈', 8.7, 11534, 'VNDB', 'https://vndb.org/v4', 'https://zh.moegirl.org.cn/CLANNAD', '', 'https://vndb.org/v4', 'https://store.steampowered.com/app/324160/', 'https://store.steampowered.com/app/324160/', '[{"name": "VNDB", "url": "https://vndb.org/v4", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/CLANNAD", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}, {"name": "Steam 商店页", "url": "https://store.steampowered.com/app/324160/", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["发行信息核对", "开发商核对", "平台核对"]}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：PC 初版；Steam HD 版于 2015-11-23 发行。', 1, 1, '2026-10-26T12:17:01+08:00')
ON DUPLICATE KEY UPDATE `name_zh` = VALUES(`name_zh`), `name_original` = VALUES(`name_original`), `aliases` = VALUES(`aliases`), `short_intro` = VALUES(`short_intro`), `intro` = VALUES(`intro`), `cover` = VALUES(`cover`), `developer` = VALUES(`developer`), `release_date` = VALUES(`release_date`), `release_year` = VALUES(`release_year`), `release_note` = VALUES(`release_note`), `platforms` = VALUES(`platforms`), `genres` = VALUES(`genres`), `rating` = VALUES(`rating`), `rating_count` = VALUES(`rating_count`), `rating_source` = VALUES(`rating_source`), `rating_source_url` = VALUES(`rating_source_url`), `moegirl_url` = VALUES(`moegirl_url`), `bangumi_url` = VALUES(`bangumi_url`), `vndb_url` = VALUES(`vndb_url`), `official_url` = VALUES(`official_url`), `steam_url` = VALUES(`steam_url`), `sources_json` = VALUES(`sources_json`), `source_note` = VALUES(`source_note`), `featured` = VALUES(`featured`), `sort_order` = VALUES(`sort_order`), `fetched_at` = VALUES(`fetched_at`);
INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('air', 'AIR', 'AIR', 'AIR ～エア～ / 青空', '旅行人偶师国崎往人来到海边小镇，寻找传说中“天空中的女孩”。', '以人偶表演为生的旅行者国崎往人，带着一个不会说话的旧人偶来到海边小镇，寻找传说中“天空中的女孩”。他在夏日的小镇里结识了神尾观铃等少女，并在日常相处中逐渐接近一段与翼人传说相连的古老因缘。作品以夏日、海风与天空为背景，恋爱与奇幻交织，基调温柔而感伤。', '/galgame/air.jpg', 'Key', '2000-09-08', 2000, 'PC 初版', 'PC (Windows) / Linux / iOS / Android / Game Boy Advance / Game Boy Color / PSP / PS2 / PS Vita / Nintendo Switch / 手机', '恋爱,奇幻,剧情,治愈', 7.8, 2992, 'VNDB', 'https://vndb.org/v36', 'https://zh.moegirl.org.cn/AIR', '', 'https://vndb.org/v36', 'https://store.steampowered.com/app/2983250/', 'https://store.steampowered.com/app/2983250/', '[{"name": "VNDB", "url": "https://vndb.org/v36", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/AIR", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}, {"name": "Steam 商店页", "url": "https://store.steampowered.com/app/2983250/", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["发行信息核对", "开发商核对", "平台核对"]}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：PC 初版。', 0, 2, '2026-10-26T12:17:01+08:00')
ON DUPLICATE KEY UPDATE `name_zh` = VALUES(`name_zh`), `name_original` = VALUES(`name_original`), `aliases` = VALUES(`aliases`), `short_intro` = VALUES(`short_intro`), `intro` = VALUES(`intro`), `cover` = VALUES(`cover`), `developer` = VALUES(`developer`), `release_date` = VALUES(`release_date`), `release_year` = VALUES(`release_year`), `release_note` = VALUES(`release_note`), `platforms` = VALUES(`platforms`), `genres` = VALUES(`genres`), `rating` = VALUES(`rating`), `rating_count` = VALUES(`rating_count`), `rating_source` = VALUES(`rating_source`), `rating_source_url` = VALUES(`rating_source_url`), `moegirl_url` = VALUES(`moegirl_url`), `bangumi_url` = VALUES(`bangumi_url`), `vndb_url` = VALUES(`vndb_url`), `official_url` = VALUES(`official_url`), `steam_url` = VALUES(`steam_url`), `sources_json` = VALUES(`sources_json`), `source_note` = VALUES(`source_note`), `featured` = VALUES(`featured`), `sort_order` = VALUES(`sort_order`), `fetched_at` = VALUES(`fetched_at`);
INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('kanon', 'Kanon', 'Kanon', 'カノン / 華音', '七年未归的少年回到北方雪国小镇，与表妹和数位少女重逢。', '时隔七年，少年相泽祐一回到被大雪覆盖的北方小镇，暂住在表妹水濑名雪家中。他陆续与数位少女重逢，也在熟悉的街景里拾起一些模糊的童年记忆。随着冬日日常推进，少女们各自怀抱的“奇迹”与祐一遗忘的过去逐渐浮现。作品以雪国小镇为舞台，描写恋爱、校园与离别。', '/galgame/kanon.jpg', 'Key', '1999-06-04', 1999, 'PC 初版；后续推出全年龄版并移植多平台', 'PC (Windows) / Linux / iOS / Android / Game Boy Advance / PSP / PS2 / PS Vita / Nintendo Switch / 手机', '恋爱,校园,剧情,治愈', 7.7, 4439, 'VNDB', 'https://vndb.org/v33', 'https://zh.moegirl.org.cn/Kanon', '', 'https://vndb.org/v33', 'https://store.steampowered.com/app/2850310/', 'https://store.steampowered.com/app/2850310/', '[{"name": "VNDB", "url": "https://vndb.org/v33", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/Kanon", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}, {"name": "Steam 商店页", "url": "https://store.steampowered.com/app/2850310/", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["发行信息核对", "开发商核对", "平台核对"]}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：PC 初版；后续推出全年龄版并移植多平台。', 0, 3, '2026-10-26T12:17:01+08:00')
