INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('rewrite', 'Rewrite', 'Rewrite', 'リライト / Rewrite+', '在绿化覆盖的风祭市，高中生天王寺瑚太朗与伙伴调查超自然事件。', '故事发生在被树木与花草覆盖的都市风祭市。高中生天王寺瑚太朗拥有改写自身身体的能力，他同几位少女一起调查城市里的超自然传闻。随着调查深入，看似平静的校园生活与城市背后的组织、能力和“改写”的真相逐渐交错。作品融合奇幻、悬疑与恋爱，并带有Key社少见的严肃氛围。', '/galgame/rewrite.jpg', 'Key', '2011-06-24', 2011, 'PC 初版；Rewrite+ 为后续强化版', 'PC (Windows) / PSP / PS3 / PS4 / PS Vita', '奇幻,悬疑,校园,恋爱', 8.5, 8485, 'VNDB', 'https://vndb.org/v751', 'https://zh.moegirl.org.cn/Rewrite(%E6%B8%B8%E6%88%8F)', '', 'https://vndb.org/v751', 'https://store.steampowered.com/app/1680000/', 'https://store.steampowered.com/app/1680000/', '[{"name": "VNDB", "url": "https://vndb.org/v751", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/Rewrite(%E6%B8%B8%E6%88%8F)", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}, {"name": "Steam 商店页", "url": "https://store.steampowered.com/app/1680000/", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["发行信息核对", "开发商核对", "平台核对"]}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：PC 初版；Rewrite+ 为后续强化版。', 0, 4, '2026-10-26T12:17:01+08:00')
ON DUPLICATE KEY UPDATE `name_zh` = VALUES(`name_zh`), `name_original` = VALUES(`name_original`), `aliases` = VALUES(`aliases`), `short_intro` = VALUES(`short_intro`), `intro` = VALUES(`intro`), `cover` = VALUES(`cover`), `developer` = VALUES(`developer`), `release_date` = VALUES(`release_date`), `release_year` = VALUES(`release_year`), `release_note` = VALUES(`release_note`), `platforms` = VALUES(`platforms`), `genres` = VALUES(`genres`), `rating` = VALUES(`rating`), `rating_count` = VALUES(`rating_count`), `rating_source` = VALUES(`rating_source`), `rating_source_url` = VALUES(`rating_source_url`), `moegirl_url` = VALUES(`moegirl_url`), `bangumi_url` = VALUES(`bangumi_url`), `vndb_url` = VALUES(`vndb_url`), `official_url` = VALUES(`official_url`), `steam_url` = VALUES(`steam_url`), `sources_json` = VALUES(`sources_json`), `source_note` = VALUES(`source_note`), `featured` = VALUES(`featured`), `sort_order` = VALUES(`sort_order`), `fetched_at` = VALUES(`fetched_at`);
INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('summer-pockets', 'Summer Pockets', 'Summer Pockets', 'サマーポケッツ / 夏日口袋 / サマポケ', '少年为整理祖母遗物来到濑户内海的孤岛，度过一个充满谜团的夏天。', '高中生鹰原羽依里离开城市，来到濑户内海的孤岛鸟白岛，替祖母整理遗物。他在岛上遇见了失去暑假记忆的鸣濑白羽、追寻岛屿传说的空门苍等少女，并在蝉鸣、海风与祭典中度过一段悠闲夏日。随着假期推进，岛上流传的古老习俗与少女们的心事慢慢浮出水面。作品以夏日孤岛为舞台，基调清新而治愈。', '/galgame/summer-pockets.jpg', 'Key', '2018-06-29', 2018, 'PC 初版', 'PC (Windows) / iOS / Android / PS4 / Nintendo Switch', '恋爱,治愈,剧情,日常', 8.5, 4813, 'VNDB', 'https://vndb.org/v20424', 'https://zh.moegirl.org.cn/Summer_Pockets', '', 'https://vndb.org/v20424', 'https://store.steampowered.com/app/897220/', 'https://store.steampowered.com/app/897220/', '[{"name": "VNDB", "url": "https://vndb.org/v20424", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/Summer_Pockets", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}, {"name": "Steam 商店页", "url": "https://store.steampowered.com/app/897220/", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["发行信息核对", "开发商核对", "平台核对"]}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：PC 初版。', 1, 5, '2026-10-26T12:17:01+08:00')
ON DUPLICATE KEY UPDATE `name_zh` = VALUES(`name_zh`), `name_original` = VALUES(`name_original`), `aliases` = VALUES(`aliases`), `short_intro` = VALUES(`short_intro`), `intro` = VALUES(`intro`), `cover` = VALUES(`cover`), `developer` = VALUES(`developer`), `release_date` = VALUES(`release_date`), `release_year` = VALUES(`release_year`), `release_note` = VALUES(`release_note`), `platforms` = VALUES(`platforms`), `genres` = VALUES(`genres`), `rating` = VALUES(`rating`), `rating_count` = VALUES(`rating_count`), `rating_source` = VALUES(`rating_source`), `rating_source_url` = VALUES(`rating_source_url`), `moegirl_url` = VALUES(`moegirl_url`), `bangumi_url` = VALUES(`bangumi_url`), `vndb_url` = VALUES(`vndb_url`), `official_url` = VALUES(`official_url`), `steam_url` = VALUES(`steam_url`), `sources_json` = VALUES(`sources_json`), `source_note` = VALUES(`source_note`), `featured` = VALUES(`featured`), `sort_order` = VALUES(`sort_order`), `fetched_at` = VALUES(`fetched_at`);
INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('planetarian', '星之梦', 'planetarian ～ちいさなほしのゆめ～', 'planetarian～小小的星之梦～ / planetarian ～ちいさなほしのゆめ～', '末日废墟中的猎人闯入无人天文馆，遇见仍在等待客人的机器人星野梦美。', '在人类文明近乎终结的未来，一名靠搜刮废墟为生的“废墟猎人”潜入被称作“棺之城”的危险都市。他在一座废弃天文馆里遇见了机器人星野梦美。她仍坚信自己是解说员，并等待了三十年未至的客人。为了修复损坏的投影仪，两人开始一段短暂而安静的相处。作品是线性短篇视觉小说，以末世与星空为背景。', '/galgame/planetarian.jpg', 'Key', '2004-11-29', 2004, 'PC 初版；Steam HD 版于 2016 年发行', 'PC (Windows) / Linux / macOS / iOS / Android / Nintendo DS / PSP / PS2 / PS Vita / Nintendo Switch / 网页 / 手机', '科幻,剧情,治愈,视觉小说', 7.8, 8731, 'VNDB', 'https://vndb.org/v34', 'https://zh.moegirl.org.cn/%E6%98%9F%E4%B9%8B%E6%A2%A6(%E6%B8%B8%E6%88%8F)', '', 'https://vndb.org/v34', 'https://store.steampowered.com/app/623080/', 'https://store.steampowered.com/app/623080/', '[{"name": "VNDB", "url": "https://vndb.org/v34", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/%E6%98%9F%E4%B9%8B%E6%A2%A6(%E6%B8%B8%E6%88%8F)", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}, {"name": "Steam 商店页", "url": "https://store.steampowered.com/app/623080/", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["发行信息核对", "开发商核对", "平台核对"]}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：PC 初版；Steam HD 版于 2016 年发行。', 0, 6, '2026-10-26T12:17:01+08:00')
