INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('harmonia', 'Harmonia', 'Harmonia -ハルモニア-', 'ハルモニア', '大战后的荒芜世界，拥有情感的人形机器人在废弃设施中苏醒，开始学习人类的心。', '在遥远未来的大战之后，被污染的天空降下灰烬，水源枯竭，人类人口大幅减少。一台被称为“Phiroid”的情感型人形机器人在废弃设施中醒来，却发现自己尚未完成，右手还露着机械结构。他渴望理解人类的情感，在荒芜世界中流浪，直到一位少女把他当作人类收留。作品以末日后的安静小镇为舞台，描写机器人学习喜怒哀乐的过程。', '/galgame/harmonia.jpg', 'Key', '2016-09-23', 2016, 'PC 初版', 'PC (Windows) / Linux / PS Vita / Nintendo Switch', '科幻,剧情,治愈,视觉小说', 6.9, 1422, 'VNDB', 'https://vndb.org/v16510', 'https://zh.moegirl.org.cn/Harmonia(Key)', '', 'https://vndb.org/v16510', 'https://store.steampowered.com/app/421660/', 'https://store.steampowered.com/app/421660/', '[{"name": "VNDB", "url": "https://vndb.org/v16510", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/Harmonia(Key)", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}, {"name": "Steam 商店页", "url": "https://store.steampowered.com/app/421660/", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["发行信息核对", "开发商核对", "平台核对"]}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：PC 初版。', 0, 7, '2026-10-26T12:17:01+08:00')
