INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('atri', 'ATRI -My Dear Moments-', 'ATRI -My Dear Moments-', 'ATRI / 亚托莉 -我挚爱的时光-', '海面上升后的近未来，少年从海底打捞起机器人少女亚托莉。', '近未来，海面上升淹没了大片陆地，少年斑鸠夏生回到海边小镇，靠打捞海底物资维持生活。一次潜水作业中，他打捞起一台机器人少女亚托莉。她声称要执行“主人的命令”，并执意陪伴夏生度过这个暑假。两人在小镇里认识居民、修复设备，也逐渐面对亚托莉身上未解的谜团。作品以海洋与校园为背景，恋爱与科幻元素并重。', '/galgame/atri.jpg', 'Frontwing / ANIPLEX.EXE', '2020-06-18', 2020, 'Steam / DMM 版首发；萌娘百科记载为 2020-06-19', 'PC (Windows) / iOS / Android / PS Vita / Nintendo Switch', '科幻,恋爱,治愈,剧情', 7.8, 3692, 'VNDB', 'https://vndb.org/v27448', 'https://zh.moegirl.org.cn/ATRI_-My_Dear_Moments-', '', 'https://vndb.org/v27448', 'https://atri-mdm.com/', 'https://store.steampowered.com/app/1230140/', '[{"name": "VNDB", "url": "https://vndb.org/v27448", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/ATRI_-My_Dear_Moments-", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}, {"name": "Steam 商店页", "url": "https://store.steampowered.com/app/1230140/", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["发行信息核对", "开发商核对", "平台核对"]}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：Steam / DMM 版首发；萌娘百科记载为 2020-06-19。', 1, 8, '2026-10-26T12:17:01+08:00')
