INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('steins-gate', '命运石之门', 'STEINS;GATE', 'STEINS;GATE / シュタインズ・ゲート / S;G', '秋叶原的自称科学家与伙伴偶然做出能向过去发送短信的装置。', '在秋叶原，自称疯狂科学家的冈部伦太郎与伙伴们经营着小小的“未来道具研究所”。一次偶然，他们发现改造过的微波炉能够把短信送往过去。随着实验不断升级，一行人被卷入围绕大型强子对撞机、神秘组织 SERN 与自称未来人的约翰·提托的阴谋。作品以时间旅行和世界线为核心，融合科幻、悬疑与群像剧。', '/galgame/steins-gate.jpg', '5pb. / Nitroplus', '2009-10-15', 2009, 'Xbox 360 初版；PC 版于 2010-08-26 发行', 'PC (Windows) / Linux / iOS / Android / PSP / PS3 / PS4 / PS5 / PS Vita / Nintendo Switch / Nintendo Switch 2 / Xbox 360', '科幻,悬疑,剧情,冒险', 9.0, 17083, 'VNDB', 'https://vndb.org/v2002', 'https://zh.moegirl.org.cn/%E5%91%BD%E8%BF%90%E7%9F%B3%E4%B9%8B%E9%97%A8%E7%B3%BB%E5%88%97', '', 'https://vndb.org/v2002', 'https://steinsgate.jp/', 'https://store.steampowered.com/app/412830/', '[{"name": "VNDB", "url": "https://vndb.org/v2002", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/%E5%91%BD%E8%BF%90%E7%9F%B3%E4%B9%8B%E9%97%A8%E7%B3%BB%E5%88%97", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}, {"name": "Steam 商店页", "url": "https://store.steampowered.com/app/412830/", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["发行信息核对", "开发商核对", "平台核对"]}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：Xbox 360 初版；PC 版于 2010-08-26 发行。', 1, 9, '2026-10-26T12:17:01+08:00')
