INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('steins-gate-0', '命运石之门0', 'STEINS;GATE 0', 'STEINS;GATE 0 / シュタインズ・ゲート ゼロ / S;G 0', '在未能拯救重要之人的β世界线，冈部伦太郎放弃时间机器，试图回归普通生活。', '故事发生在“没能拯救她”的β世界线。经历了无数次世界线跳跃的冈部伦太郎陷入绝望，放弃继续使用时间机器，努力扮演一名普通大学生。一次学术发表会让他接触到将记忆数字化的“Amadeus”计划，也让他再次被卷入黑暗组织的阴谋。本作承接《命运石之门》的β世界线，基调比前作更为沉重。', '/galgame/steins-gate-0.jpg', 'MAGES. / 5pb.', '2015-12-10', 2015, 'PS3 / PS4 / PS Vita 初版；PC 版后续发行', 'PC (Windows) / PS3 / PS4 / PS Vita / Nintendo Switch / Xbox One', '科幻,悬疑,剧情,冒险', 8.1, 7734, 'VNDB', 'https://vndb.org/v17102', 'https://zh.moegirl.org.cn/%E5%91%BD%E8%BF%90%E7%9F%B3%E4%B9%8B%E9%97%A80', '', 'https://vndb.org/v17102', 'https://store.steampowered.com/app/825630/', 'https://store.steampowered.com/app/825630/', '[{"name": "VNDB", "url": "https://vndb.org/v17102", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/%E5%91%BD%E8%BF%90%E7%9F%B3%E4%B9%8B%E9%97%A80", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}, {"name": "Steam 商店页", "url": "https://store.steampowered.com/app/825630/", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["发行信息核对", "开发商核对", "平台核对"]}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：PS3 / PS4 / PS Vita 初版；PC 版后续发行。', 0, 10, '2026-10-26T12:17:01+08:00')
