INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('mahoyo', '魔法使之夜', '魔法使いの夜', '魔法使いの夜 / Witch on the Holy Night / Mahoyo', '1980年代末，两名隐居山中宅邸的魔术师与偶然闯入的少年开始了奇妙同居。', '故事发生在昭和末期的 1980 年代末。刚接触魔术的青子与同为魔术师的久远寺有珠隐居在山中宅邸，过着与世隔绝的生活。少年静希草十郎偶然闯入她们的世界，三人从此开始一段奇妙而同居的日子。作品以魔术师的世界为背景，描写三人之间的日常与冲突，是 TYPE-MOON 月世界体系中的独立篇章。', '/galgame/mahoyo.jpg', 'TYPE-MOON', '2012-04-12', 2012, 'PC 初版；主机版于 2022 年发行', 'PC (Windows) / PS4 / Nintendo Switch', '奇幻,剧情,视觉小说,日常', 8.6, 5659, 'VNDB', 'https://vndb.org/v777', 'https://zh.moegirl.org.cn/%E9%AD%94%E6%B3%95%E4%BD%BF%E4%B9%8B%E5%A4%9C', '', 'https://vndb.org/v777', 'https://typemoon.com/products/mahoyo/', 'https://store.steampowered.com/app/2052410/', '[{"name": "VNDB", "url": "https://vndb.org/v777", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/%E9%AD%94%E6%B3%95%E4%BD%BF%E4%B9%8B%E5%A4%9C", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}, {"name": "Steam 商店页", "url": "https://store.steampowered.com/app/2052410/", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["发行信息核对", "开发商核对", "平台核对"]}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：PC 初版；主机版于 2022 年发行。', 0, 11, '2026-10-26T12:17:01+08:00')
