INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('428', '428 ～被封锁的涩谷～', '428 〜封鎖された渋谷で〜', '428 〜封鎖された渋谷で〜 / 428: Shibuya Scramble', '涩谷街头，侦探、青年、病毒研究员、自由撰稿人和一只猫吉祥物被一连串事件联系起来。', '故事发生在东京涩谷。一名侦探、一名青年、一名病毒研究员、一名自由撰稿人和一只猫吉祥物，因为一连串看似无关的突发事件被联系在一起。玩家以多线并行的方式推进不同主角的视角，在有限时间内逐步拼出事件全貌。作品采用真人照片与影像素材，融合悬疑、群像剧与多结局结构。', '/galgame/428.jpg', 'Chunsoft / Spike Chunsoft', '2008-12-04', 2008, 'Wii 初版；PS3 / PSP 版于 2009 年发行，PC 版于 2018 年发行', 'PC (Windows) / iOS / Android / PSP / PS3 / PS4 / Wii', '悬疑,剧情,冒险,视觉小说', 8.4, 1729, 'VNDB', 'https://vndb.org/v1299', 'https://zh.moegirl.org.cn/428_%EF%BD%9E%E8%A2%AB%E5%B0%81%E9%94%81%E7%9A%84%E6%B6%A9%E8%B0%B7%EF%BD%9E', '', 'https://vndb.org/v1299', 'https://store.steampowered.com/app/648580/', 'https://store.steampowered.com/app/648580/', '[{"name": "VNDB", "url": "https://vndb.org/v1299", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/428_%EF%BD%9E%E8%A2%AB%E5%B0%81%E9%94%81%E7%9A%84%E6%B6%A9%E8%B0%B7%EF%BD%9E", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}, {"name": "Steam 商店页", "url": "https://store.steampowered.com/app/648580/", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["发行信息核对", "开发商核对", "平台核对"]}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：Wii 初版；PS3 / PSP 版于 2009 年发行，PC 版于 2018 年发行。', 0, 12, '2026-10-26T12:17:01+08:00')
