INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('999', '极限脱出：9小时9人9扇门', '極限脱出 9時間9人9の扉', '極限脱出 9時間9人9の扉 / Zero Escape: Nine Hours, Nine Persons, Nine Doors / 999', '九名互不相识的人被自称“零”的人绑架，囚禁在一艘船上参加九人游戏。', '九名互不相识的人被自称“零”的神秘人绑架，囚禁在一艘正在下沉的船上。他们被迫参加“九人游戏”，必须在九小时内解开密室谜题，穿过编号门才能到达出口。每个人手腕上的编号既是通行证，也是彼此合作的筹码。作品将密室逃脱、推理解谜与多结局叙事结合，是“极限脱出”系列的第一作。', '/galgame/999.jpg', 'Chunsoft / Spike Chunsoft', '2009-12-10', 2009, 'Nintendo DS 初版；后续推出 iOS 与合集版', 'PC (Windows) / iOS / Nintendo DS / PS4 / PS Vita / Xbox One / Xbox Series X/S / 网页', '悬疑,剧情,冒险,视觉小说', 8.3, 9135, 'VNDB', 'https://vndb.org/v3112', 'https://zh.moegirl.org.cn/%E6%9E%81%E9%99%90%E8%84%B1%E5%87%BA%EF%BC%9A9%E5%B0%8F%E6%97%B69%E4%BA%BA9%E6%89%87%E9%97%A8', '', 'https://vndb.org/v3112', '', '', '[{"name": "VNDB", "url": "https://vndb.org/v3112", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/%E6%9E%81%E9%99%90%E8%84%B1%E5%87%BA%EF%BC%9A9%E5%B0%8F%E6%97%B69%E4%BA%BA9%E6%89%87%E9%97%A8", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：Nintendo DS 初版；后续推出 iOS 与合集版。', 0, 13, '2026-10-26T12:17:01+08:00')
