INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('fata-morgana', '海市蜃楼之馆', 'ファタモルガーナの館', 'ファタモルガーナの館 / The House in Fata Morgana / Fata Moru', '失去记忆的“你”在古老宅邸醒来，一位翡翠瞳色的女仆带你观看历任主人的悲剧。', '“你”在一座破败的古老宅邸中醒来，失去了记忆，甚至无法确定自己是否还活着。眼前只有一位瞳色如翡翠的女仆，她称“你”为宅邸的主人，并邀请“你”穿过一扇扇门，观看宅邸历任居住者经历的悲剧。她相信，这些故事里或许藏着“你”的过去。作品以哥特式宅邸为舞台，采用单元剧结构，融合悬疑、恋爱与悲剧。', '/galgame/fata-morgana.jpg', 'Novectacle', '2012-12-31', 2012, 'PC 初版；Steam 版后续发行', 'PC (Windows) / iOS / Android / PS4 / PS Vita / Nintendo Switch / Nintendo 3DS', '悬疑,剧情,恋爱,视觉小说', 8.8, 7750, 'VNDB', 'https://vndb.org/v12402', 'https://zh.moegirl.org.cn/%E6%B5%B7%E5%B8%82%E8%9C%83%E6%A5%BC%E4%B9%8B%E9%A6%86', '', 'https://vndb.org/v12402', 'https://novect.net/', 'https://store.steampowered.com/app/303310/', '[{"name": "VNDB", "url": "https://vndb.org/v12402", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/%E6%B5%B7%E5%B8%82%E8%9C%83%E6%A5%BC%E4%B9%8B%E9%A6%86", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}, {"name": "Steam 商店页", "url": "https://store.steampowered.com/app/303310/", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["发行信息核对", "开发商核对", "平台核对"]}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：PC 初版；Steam 版后续发行。', 1, 14, '2026-10-26T12:17:01+08:00')
