INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('gaokao', '高考恋爱100天', '高考恋爱一百天', '高考恋爱一百天 / Gaokao Love 100Days / 高恋', '高三男生在高考前一百天向暗恋的女生告白，恋爱与备考同时到来。', '故事从高三男生向暗恋的女生木馨告白开始。距离高考只剩一百天，两人终于成为恋人，但备考的压力、家庭的期待和未来的选择也接踵而至。玩家需要在有限的时间里安排学习、约会与社交，平衡成绩和感情，并面对多条分支带来的不同结局。作品以中国高中生活为背景，是国产恋爱养成视觉小说。', '/galgame/gaokao.jpg', '落叶岛项目组', '2014-07-20', 2014, '实体版初版；Steam 版于 2015-05-30 发行，Switch 版于 2018 年发行', 'PC (Windows) / Nintendo Switch / 网页', '恋爱,校园,剧情,日常', 6.6, 268, 'VNDB', 'https://vndb.org/v17716', 'https://zh.moegirl.org.cn/%E9%AB%98%E8%80%83%E6%81%8B%E7%88%B1%E4%B8%80%E7%99%BE%E5%A4%A9', '', 'https://vndb.org/v17716', 'https://store.steampowered.com/app/347620/', 'https://store.steampowered.com/app/347620/', '[{"name": "VNDB", "url": "https://vndb.org/v17716", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/%E9%AB%98%E8%80%83%E6%81%8B%E7%88%B1%E4%B8%80%E7%99%BE%E5%A4%A9", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}, {"name": "Steam 商店页", "url": "https://store.steampowered.com/app/347620/", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["发行信息核对", "开发商核对", "平台核对"]}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：实体版初版；Steam 版于 2015-05-30 发行，Switch 版于 2018 年发行。', 0, 15, '2026-10-26T12:17:01+08:00')
