INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('lucy', '露西 -她所期望的一切-', '루시 - 그녀가 바라던 것 -', '루시 - 그녀가 바라던 것 - / Lucy -The Eternity She Wished For- / 露西', '在仿生人已融入社会的近未来，少年在垃圾场捡到一台会笑会哭的机器人少女。', '在近未来，仿生人已经成为人类社会的一部分，但少年并不喜欢这些没有感情的金属造物。某天，他在垃圾场捡到一台与众不同的机器人少女露西：她会笑、会哭，也会做梦，像人类一样表达情感。少年把她带回家，开始一段关于人与机器人如何相处的故事。作品以近未来为背景，探讨情感、记忆与“何以为人”。', '/galgame/lucy.jpg', 'M-Vizlab', '2010', 2010, '韩文初版于 2010 年；Steam 中文版后续发行', 'PC (Windows) / iOS / Android', '科幻,恋爱,剧情,治愈', 7.3, 1695, 'VNDB', 'https://vndb.org/v16743', 'https://zh.moegirl.org.cn/%E9%9C%B2%E8%A5%BF_-%E5%A5%B9%E6%89%80%E6%9C%9F%E6%9C%9B%E7%9A%84%E4%B8%80%E5%88%87-', '', 'https://vndb.org/v16743', 'https://store.steampowered.com/app/430960/', 'https://store.steampowered.com/app/430960/', '[{"name": "VNDB", "url": "https://vndb.org/v16743", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/%E9%9C%B2%E8%A5%BF_-%E5%A5%B9%E6%89%80%E6%9C%9F%E6%9C%9B%E7%9A%84%E4%B8%80%E5%88%87-", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}, {"name": "Steam 商店页", "url": "https://store.steampowered.com/app/430960/", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["发行信息核对", "开发商核对", "平台核对"]}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：韩文初版于 2010 年；Steam 中文版后续发行。 萌娘百科页面摘要为空，简介依据 VNDB 与公开商店页整理。', 0, 16, '2026-10-26T12:17:01+08:00')
