INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('narcissu', '水仙', 'narcissu', 'ナルキッソス / narcissu / Narcissu', '二十岁的主人公被诊断绝症，在医院遇到同样患病的少女濑津美。', '二十岁的主人公在生日后不久被诊断出绝症，住进医院。他在那里遇见了同样患病的少女濑津美。两人都不愿在医院或家中迎来生命的终点，于是偷走一辆车，踏上一段没有明确目的地的公路旅行。作品没有分支选项和人物立绘，以平淡克制的文字描写生死、陪伴与告别，是短篇视觉小说的代表作之一。', '/galgame/narcissu.jpg', 'Stage-nana', '2005-08-02', 2005, '同人版初版；Steam 版后续发行', 'PC (Windows) / Linux / macOS / iOS / Android / Game Boy Advance / Nintendo DS / PSP / 网页', '剧情,治愈,视觉小说', 7.5, 7116, 'VNDB', 'https://vndb.org/v10', 'https://zh.moegirl.org.cn/Narcissu', '', 'https://vndb.org/v10', 'https://store.steampowered.com/app/264380/', 'https://store.steampowered.com/app/264380/', '[{"name": "VNDB", "url": "https://vndb.org/v10", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/Narcissu", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}, {"name": "Steam 商店页", "url": "https://store.steampowered.com/app/264380/", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["发行信息核对", "开发商核对", "平台核对"]}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：同人版初版；Steam 版后续发行。', 0, 17, '2026-10-26T12:17:01+08:00')
