INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('higurashi', '寒蝉鸣泣之时', 'ひぐらしのなく頃に', 'ひぐらしのなく頃に / Higurashi When They Cry / 寒蝉鸣泣之时 出题篇', '1983年夏，少年搬到偏僻的雏见泽村，与伙伴们度过日常，也撞见村庄的黑暗秘密。', '1983 年夏天，少年前原圭一搬到偏僻的雏见泽村，很快与礼奈、魅音、诗音、梨花等伙伴打成一片。村庄看似宁静，但每年绵流祭前后都会发生离奇的死亡与失踪事件。随着祭典临近，圭一逐渐发现伙伴们似乎隐瞒着什么。作品以昭和乡村为舞台，采用多篇章轮回结构，融合悬疑、恐怖与友情。', '/galgame/higurashi.jpg', '07th Expansion', '2002-08-10', 2002, '出题篇第一作初版；系列于 2002-2006 年陆续发售', 'PC (Windows) / Linux / macOS / iOS / Android / Game Boy Advance / Nintendo DS / PS2 / PS3 / PS4 / PS Vita / Nintendo Switch / 手机', '悬疑,剧情,奇幻,视觉小说', 8.6, 11433, 'VNDB', 'https://vndb.org/v67', 'https://zh.moegirl.org.cn/%E5%AF%92%E8%9D%89%E9%B8%A3%E6%B3%A3%E4%B9%8B%E6%97%B6', '', 'https://vndb.org/v67', '', '', '[{"name": "VNDB", "url": "https://vndb.org/v67", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/%E5%AF%92%E8%9D%89%E9%B8%A3%E6%B3%A3%E4%B9%8B%E6%97%B6", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：出题篇第一作初版；系列于 2002-2006 年陆续发售。', 0, 18, '2026-10-26T12:17:01+08:00')
