INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('umineko', '海猫鸣泣之时', 'うみねこのなく頃に', 'うみねこのなく頃に / Umineko When They Cry / 海猫鸣泣之时 出题篇', '1986年，右代宫家族齐聚孤岛讨论遗产，署名黄金魔女的信件与连续杀人事件接连出现。', '1986 年，右代宫家族成员齐聚孤岛六轩岛，讨论家主右代宫金藏的遗产分配。台风封岛后，一封署名黄金魔女贝阿朵莉切的信件出现，随后接连发生杀人事件。家族成员必须在猜疑与恐惧中解开魔女的谜题。作品以封闭孤岛为舞台，围绕“魔女是否存在”展开推理与幻想之争，是《寒蝉鸣泣之时》之后的又一系列长篇视觉小说。', '/galgame/umineko.jpg', '07th Expansion', '2007-08-17', 2007, '出题篇第一作初版；系列于 2007-2010 年陆续发售', 'PC (Windows) / Linux / macOS / iOS / Android / PSP / PS3 / PS4 / PS5 / PS Vita / Nintendo Switch / Xbox One / Xbox Series X/S / 网页', '悬疑,奇幻,剧情,视觉小说', 8.9, 14065, 'VNDB', 'https://vndb.org/v24', 'https://zh.moegirl.org.cn/%E6%B5%B7%E7%8C%AB%E9%B8%A3%E6%B3%A3%E4%B9%8B%E6%97%B6', '', 'https://vndb.org/v24', 'https://store.steampowered.com/app/406550/', 'https://store.steampowered.com/app/406550/', '[{"name": "VNDB", "url": "https://vndb.org/v24", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/%E6%B5%B7%E7%8C%AB%E9%B8%A3%E6%B3%A3%E4%B9%8B%E6%97%B6", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}, {"name": "Steam 商店页", "url": "https://store.steampowered.com/app/406550/", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["发行信息核对", "开发商核对", "平台核对"]}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：出题篇第一作初版；系列于 2007-2010 年陆续发售。', 0, 19, '2026-10-26T12:17:01+08:00')
