INSERT INTO `tb_galgame` (`slug`, `name_zh`, `name_original`, `aliases`, `short_intro`, `intro`, `cover`, `developer`, `release_date`, `release_year`, `release_note`, `platforms`, `genres`, `rating`, `rating_count`, `rating_source`, `rating_source_url`, `moegirl_url`, `bangumi_url`, `vndb_url`, `official_url`, `steam_url`, `sources_json`, `source_note`, `featured`, `sort_order`, `fetched_at`) VALUES ('white-album-2', '白色相簿2', 'WHITE ALBUM2', 'WHITE ALBUM2 / ホワイトアルバム2 / WA2', '高中轻音乐同好会里，三名少年少女因一首歌相遇，在爱情与友情之间走向选择。', '高中轻音乐同好会里，北原春希、小木曾雪菜与冬马和纱因一首歌走到一起。三人度过了一段短暂而耀眼的青春时光，也在这段关系里埋下无法回避的情感纠葛。故事从学园祭前后的相遇开始，逐渐延伸到大学与成年后的选择。作品以细腻的心理描写和音乐场景著称，是恋爱视觉小说中常被讨论的代表作。', '/galgame/white-album-2.jpg', 'Leaf / AQUAPLUS', '2010-03-26', 2010, 'Introductory Chapter 初版；Closing Chapter 于 2011-12-22 发行', 'PC (Windows) / PSP / PS3 / PS Vita', '恋爱,剧情,校园,视觉小说', 9.0, 4649, 'VNDB', 'https://vndb.org/v7771', 'https://zh.moegirl.org.cn/%E7%99%BD%E8%89%B2%E7%9B%B8%E7%B0%BF2', '', 'https://vndb.org/v7771', '', '', '[{"name": "VNDB", "url": "https://vndb.org/v7771", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["原名", "发行日期", "开发商", "支持平台", "评分", "评分人数"]}, {"name": "萌娘百科", "url": "https://zh.moegirl.org.cn/%E7%99%BD%E8%89%B2%E7%9B%B8%E7%B0%BF2", "retrieved_at": "2026-10-26T12:17:01+08:00", "fields": ["中文名", "别名", "背景介绍"], "license": "萌娘百科内容适用 CC BY-NC-SA 3.0 CN"}]', '结构化资料取自 VNDB；中文名、别名与背景参考萌娘百科；题材标签根据 VNDB 标签与萌娘百科介绍人工整理。 版本说明：Introductory Chapter 初版；Closing Chapter 于 2011-12-22 发行。', 1, 20, '2026-10-26T12:17:01+08:00')
